class URLHandler:
    SCHEME_SEPARATOR = "://"
    MAGIC_ONE = 1
    MAGIC_TWO = 2
    MAGIC_THREE = 3
    EMPTY_STRING = ""

    def __init__(self, url):
        self.url = url

    def _find_scheme_end(self):
        scheme_end = self.url.find(URLHandler.SCHEME_SEPARATOR)
        return scheme_end

    def _get_url_without_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self.url[scheme_end + URLHandler.MAGIC_THREE:]
        return None

    def get_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self.url[:scheme_end]
        return None

    def get_host(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = url_without_scheme.find("/")
            if host_end != -1:
                return url_without_scheme[:host_end]
            return url_without_scheme
        return None

    def get_path(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = url_without_scheme.find("/")
            if host_end != -1:
                return url_without_scheme[host_end:]
        return None

    def _extract_query_string(self):
        query_start = self.url.find("?")
        if query_start != -1:
            fragment_start = self.url.find("#")
            return self.url[query_start + URLHandler.MAGIC_ONE:fragment_start]
        return None

    def _parse_params(self, query_string):
        params = {}
        if len(query_string) > 0:
            param_pairs = query_string.split("&")
            for pair in param_pairs:
                key_value = pair.split("=")
                if len(key_value) == URLHandler.MAGIC_TWO:
                    key, value = key_value
                    params[key] = value
        return params

    def get_query_params(self):
        query_string = self._extract_query_string()
        if query_string is not None:
            return self._parse_params(query_string)
        return None

    def get_fragment(self):
        fragment_start = self.url.find("#")
        if fragment_start != -1:
            return self.url[fragment_start + URLHandler.MAGIC_ONE:]
        return None
